begin;

create temporary table coding_question_seed (collection_slug text not null, slug text not null, title text not null, problem_statement text not null, difficulty text not null, topic_tags text[] not null, constraints jsonb not null, examples jsonb not null, starter_code_by_language jsonb not null, points integer not null) on commit drop;

insert into coding_question_seed select collection_slug,slug,title,problem_statement,difficulty,topic_tags,constraints,examples,starter_code_by_language,points from jsonb_to_recordset($seed$[{"collection_slug":"web-development-fundamentals","slug":"parse-query-string","title":"Parse a Query String","problem_statement":"Parse ampersand-separated query pairs into ordered [key,value] pairs. Decode percent escapes and plus signs as spaces, retain duplicate keys, and treat missing equals as an empty value.","difficulty":"Easy","topic_tags":["Web Fundamentals","Safe Data Handling"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"\"?q=red+fox&tag=a&tag=b\"","output":"[[\"q\",\"red fox\"],[\"tag\",\"a\"],[\"tag\",\"b\"]]"},{"input":"\"?flag&mode=dark\"","output":"[[\"flag\",\"\"],[\"mode\",\"dark\"]]"}],"starter_code_by_language":{"JavaScript":"function parseQueryString(query) {\n  throw new Error(\"Not implemented\");\n}","Python":"def parse_query_string(query):\n    raise NotImplementedError"},"points":100},{"collection_slug":"web-development-fundamentals","slug":"serialize-query-pairs","title":"Serialize Query Pairs","problem_statement":"Serialize ordered key/value pairs with percent encoding and plus signs for spaces. Preserve pair order and repeated keys.","difficulty":"Medium","topic_tags":["Web Fundamentals","Safe Data Handling"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"[[\"q\",\"red fox\"],[\"tag\",\"a\"],[\"tag\",\"b\"]]","output":"q=red+fox&tag=a&tag=b"},{"input":"[[\"next\",\"/a?b=1\"],[\"empty\",\"\"]]","output":"next=%2Fa%3Fb%3D1&empty="}],"starter_code_by_language":{"JavaScript":"function serializeQueryPairs(pairs) {\n  throw new Error(\"Not implemented\");\n}","Python":"def serialize_query_pairs(pairs):\n    raise NotImplementedError"},"points":150},{"collection_slug":"web-development-fundamentals","slug":"strip-tracking-parameters","title":"Strip Tracking Query Parameters","problem_statement":"Remove query pairs whose key starts with utm_ or equals fbclid or gclid, ignoring case. Preserve other pairs and order.","difficulty":"Hard","topic_tags":["Web Fundamentals","Safe Data Handling"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"[[\"q\",\"shoes\"],[\"utm_source\",\"mail\"],[\"fbclid\",\"x\"],[\"page\",\"2\"]]","output":"[[\"q\",\"shoes\"],[\"page\",\"2\"]]"},{"input":"[[\"UTM_campaign\",\"sale\"],[\"lang\",\"fr\"]]","output":"[[\"lang\",\"fr\"]]"}],"starter_code_by_language":{"JavaScript":"function stripTrackingParameters(pairs) {\n  throw new Error(\"Not implemented\");\n}","Python":"def strip_tracking_parameters(pairs):\n    raise NotImplementedError"},"points":200},{"collection_slug":"web-development-fundamentals","slug":"validate-navigation-url","title":"Validate Navigation URL","problem_statement":"Return true only for absolute URLs using http or https and containing a non-empty hostname. Reject relative URLs and all other schemes.","difficulty":"Easy","topic_tags":["Web Fundamentals","Safe Data Handling"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"\"https://example.com/account\"","output":"true"},{"input":"\"javascript:alert(1)\"","output":"false"}],"starter_code_by_language":{"JavaScript":"function isSafeNavigationUrl(value) {\n  throw new Error(\"Not implemented\");\n}","Python":"def is_safe_navigation_url(value):\n    raise NotImplementedError"},"points":100},{"collection_slug":"web-development-fundamentals","slug":"compare-url-origins","title":"Compare URL Origins","problem_statement":"Compare normalized scheme, hostname, and effective port of absolute URLs. Ignore path, query, and fragment.","difficulty":"Medium","topic_tags":["Web Fundamentals","Safe Data Handling"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"{\"first\":\"https://EXAMPLE.com/a\",\"second\":\"https://example.com:443/b?q=1\"}","output":"true"},{"input":"{\"first\":\"https://example.com\",\"second\":\"http://example.com\"}","output":"false"}],"starter_code_by_language":{"JavaScript":"function sameUrlOrigin(first, second) {\n  throw new Error(\"Not implemented\");\n}","Python":"def same_url_origin(first, second):\n    raise NotImplementedError"},"points":150},{"collection_slug":"web-development-fundamentals","slug":"remove-default-url-port","title":"Remove Default URL Port","problem_statement":"For absolute HTTP(S) URLs, remove port 80 for HTTP and 443 for HTTPS while preserving other components and non-default ports.","difficulty":"Hard","topic_tags":["Web Fundamentals","Safe Data Handling"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"\"https://example.com:443/a?q=1#top\"","output":"https://example.com/a?q=1#top"},{"input":"\"http://example.com:8080/a\"","output":"http://example.com:8080/a"}],"starter_code_by_language":{"JavaScript":"function removeDefaultUrlPort(value) {\n  throw new Error(\"Not implemented\");\n}","Python":"def remove_default_url_port(value):\n    raise NotImplementedError"},"points":200},{"collection_slug":"web-development-fundamentals","slug":"encode-path-segment","title":"Encode One URL Path Segment","problem_statement":"Percent-encode a path segment using UTF-8. Leave only RFC 3986 unreserved characters unchanged; encode slash within the input.","difficulty":"Easy","topic_tags":["Web Fundamentals","Safe Data Handling"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"\"folder/a b\"","output":"folder%2Fa%20b"},{"input":"\"caf?\"","output":"caf%C3%A9"}],"starter_code_by_language":{"JavaScript":"function encodePathSegment(segment) {\n  throw new Error(\"Not implemented\");\n}","Python":"def encode_path_segment(segment):\n    raise NotImplementedError"},"points":100},{"collection_slug":"web-development-fundamentals","slug":"normalize-dot-segments","title":"Normalize URL Dot Segments","problem_statement":"Resolve literal . and .. components in an absolute URL path without changing query or fragment. Do not treat percent-encoded dots as operators.","difficulty":"Medium","topic_tags":["Web Fundamentals","Safe Data Handling"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"\"https://shop.test/a/../b/./item?x=1\"","output":"https://shop.test/b/item?x=1"},{"input":"\"https://shop.test/a/%2E%2E/b\"","output":"https://shop.test/a/%2E%2E/b"}],"starter_code_by_language":{"JavaScript":"function normalizeDotSegments(value) {\n  throw new Error(\"Not implemented\");\n}","Python":"def normalize_dot_segments(value):\n    raise NotImplementedError"},"points":150},{"collection_slug":"web-development-fundamentals","slug":"validate-same-origin-redirect","title":"Validate Same-Origin Redirect","problem_statement":"Return true only if an absolute redirect target has the same normalized origin as its base URL. Reject relative and non-HTTP targets.","difficulty":"Hard","topic_tags":["Web Fundamentals","Safe Data Handling"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"{\"base\":\"https://app.test/profile\",\"target\":\"https://app.test/settings\"}","output":"true"},{"input":"{\"base\":\"https://app.test/\",\"target\":\"https://evil.test/\"}","output":"false"}],"starter_code_by_language":{"JavaScript":"function isSameOriginRedirect(base, target) {\n  throw new Error(\"Not implemented\");\n}","Python":"def is_same_origin_redirect(base, target):\n    raise NotImplementedError"},"points":200},{"collection_slug":"web-development-fundamentals","slug":"parse-set-cookie-attributes","title":"Parse Set-Cookie Attributes","problem_statement":"Parse a Set-Cookie header into a cookie name and value plus recognized attributes. Attribute names are case-insensitive; preserve attribute values, normalize SameSite to its original token, and represent Secure and HttpOnly as booleans. Omit attributes that are not present.","difficulty":"Easy","topic_tags":["Web Fundamentals","Safe Data Handling"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"\"sid=abc; Path=/account; Secure; HttpOnly; SameSite=Lax\"","output":"{\"name\":\"sid\",\"value\":\"abc\",\"path\":\"/account\",\"secure\":true,\"httpOnly\":true,\"sameSite\":\"Lax\"}"},{"input":"\"prefs=dark; Domain=example.com; Max-Age=3600\"","output":"{\"name\":\"prefs\",\"value\":\"dark\",\"domain\":\"example.com\",\"maxAge\":3600}"}],"starter_code_by_language":{"JavaScript":"function parseSetCookieAttributes(header) {\n  throw new Error(\"Not implemented\");\n}","Python":"def parse_set_cookie_attributes(header):\n    raise NotImplementedError"},"points":100},{"collection_slug":"web-development-fundamentals","slug":"redact-sensitive-cookies","title":"Redact Sensitive Cookie Values","problem_statement":"Clone a cookie object and replace values for names containing session, auth, or token (case-insensitive) with [REDACTED]. Preserve other values.","difficulty":"Medium","topic_tags":["Web Fundamentals","Safe Data Handling"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"{\"sessionId\":\"abc\",\"theme\":\"dark\",\"AUTH\":\"bearer\"}","output":"{\"sessionId\":\"[REDACTED]\",\"theme\":\"dark\",\"AUTH\":\"[REDACTED]\"}"},{"input":"{\"cart\":\"c1\",\"token\":\"t1\"}","output":"{\"cart\":\"c1\",\"token\":\"[REDACTED]\"}"}],"starter_code_by_language":{"JavaScript":"function redactSensitiveCookies(cookies) {\n  throw new Error(\"Not implemented\");\n}","Python":"def redact_sensitive_cookies(cookies):\n    raise NotImplementedError"},"points":150},{"collection_slug":"web-development-fundamentals","slug":"parse-form-urlencoded","title":"Parse Form-Urlencoded Fields","problem_statement":"Parse form-urlencoded text, decoding percent escapes and plus-as-space. Preserve a singleton as a string and collect repeated names into arrays in encounter order.","difficulty":"Hard","topic_tags":["Web Fundamentals","Safe Data Handling"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"\"name=Ada&tag=red&tag=blue&note=hello+world\"","output":"{\"name\":\"Ada\",\"tag\":[\"red\",\"blue\"],\"note\":\"hello world\"}"},{"input":"\"next=%2Fhome&flag\"","output":"{\"next\":\"/home\",\"flag\":\"\"}"}],"starter_code_by_language":{"JavaScript":"function parseFormUrlencoded(body) {\n  throw new Error(\"Not implemented\");\n}","Python":"def parse_form_urlencoded(body):\n    raise NotImplementedError"},"points":200},{"collection_slug":"web-development-fundamentals","slug":"serialize-form-fields","title":"Serialize Form Fields","problem_statement":"Serialize object fields in lexicographic key order using form URL encoding. Arrays produce repeated key/value pairs; null values are omitted.","difficulty":"Easy","topic_tags":["Web Fundamentals","Safe Data Handling"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"{\"tag\":[\"red\",\"blue\"],\"q\":\"red fox\",\"ignored\":null}","output":"q=red+fox&tag=red&tag=blue"},{"input":"{\"next\":\"/a?b=1\",\"empty\":\"\"}","output":"empty=&next=%2Fa%3Fb%3D1"}],"starter_code_by_language":{"JavaScript":"function serializeFormFields(fields) {\n  throw new Error(\"Not implemented\");\n}","Python":"def serialize_form_fields(fields):\n    raise NotImplementedError"},"points":100},{"collection_slug":"web-development-fundamentals","slug":"collect-checked-values","title":"Collect Checked Values","problem_statement":"Return values from checkbox records only when checked is exactly true. Preserve source order and ignore records without a value.","difficulty":"Medium","topic_tags":["Web Fundamentals","Safe Data Handling"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"[{\"value\":\"email\",\"checked\":true},{\"value\":\"sms\",\"checked\":false},{\"value\":\"push\",\"checked\":true}]","output":"[\"email\",\"push\"]"},{"input":"[{\"checked\":true},{\"value\":\"weekly\",\"checked\":true}]","output":"[\"weekly\"]"}],"starter_code_by_language":{"JavaScript":"function collectCheckedValues(items) {\n  throw new Error(\"Not implemented\");\n}","Python":"def collect_checked_values(items):\n    raise NotImplementedError"},"points":150},{"collection_slug":"web-development-fundamentals","slug":"find-missing-form-fields","title":"Find Missing Required Form Fields","problem_statement":"Return required names whose value is absent, null, or blank. Values 0 and false are present; preserve required-field order.","difficulty":"Hard","topic_tags":["Web Fundamentals","Safe Data Handling"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"{\"required\":[\"name\",\"enabled\",\"quota\"],\"values\":{\"name\":\"Ada\",\"enabled\":false}}","output":"[\"quota\"]"},{"input":"{\"required\":[\"email\",\"region\"],\"values\":{\"email\":\" \"}}","output":"[\"email\",\"region\"]"}],"starter_code_by_language":{"JavaScript":"function missingFormFields(required, values) {\n  throw new Error(\"Not implemented\");\n}","Python":"def missing_form_fields(required, values):\n    raise NotImplementedError"},"points":200},{"collection_slug":"web-development-fundamentals","slug":"truncate-by-code-point","title":"Truncate by Unicode Code Point","problem_statement":"Return at most max Unicode code points from text without splitting a surrogate pair; do not append an ellipsis.","difficulty":"Easy","topic_tags":["Web Fundamentals","Safe Data Handling"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"{\"text\":\"A??BC\",\"max\":2}","output":"A??"},{"input":"{\"text\":\"r?sum?\",\"max\":4}","output":"r?su"}],"starter_code_by_language":{"JavaScript":"function truncateByCodePoint(text, max) {\n  throw new Error(\"Not implemented\");\n}","Python":"def truncate_by_code_point(text, max):\n    raise NotImplementedError"},"points":100},{"collection_slug":"web-development-fundamentals","slug":"normalize-newline-sequences","title":"Normalize Newline Sequences","problem_statement":"Convert every CRLF pair and every lone carriage return in a string to one LF character. Leave existing LF characters unchanged and do not trim the string.","difficulty":"Medium","topic_tags":["Web Fundamentals","Safe Data Handling"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"\"first\\r\\nsecond\\rthird\"","output":"first\nsecond\nthird"},{"input":"\"one\\ntwo\\nthree\"","output":"one\ntwo\nthree"}],"starter_code_by_language":{"JavaScript":"function normalizeNewlineSequences(text) {\n  throw new Error(\"Not implemented\");\n}","Python":"def normalize_newline_sequences(text):\n    raise NotImplementedError"},"points":150},{"collection_slug":"web-development-fundamentals","slug":"escape-html-attribute","title":"Escape Quoted HTML Attribute","problem_statement":"Escape ampersand, double quote, less-than, and greater-than before inserting text into a double-quoted HTML attribute.","difficulty":"Hard","topic_tags":["Web Fundamentals","Safe Data Handling"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"\"title=\"A&B\"\"","output":"title=&quot;A&amp;B&quot;"},{"input":"\"<img>\"","output":"&lt;img&gt;"}],"starter_code_by_language":{"JavaScript":"function escapeHtmlAttribute(text) {\n  throw new Error(\"Not implemented\");\n}","Python":"def escape_html_attribute(text):\n    raise NotImplementedError"},"points":200},{"collection_slug":"web-development-fundamentals","slug":"parse-css-length-token","title":"Parse a Safe CSS Length Token","problem_statement":"Parse a non-negative finite decimal followed by px, rem, or % with no embedded whitespace. Return an object containing numeric value and the exact unit; reject negative values and unsupported units by returning null.","difficulty":"Easy","topic_tags":["Web Fundamentals","Safe Data Handling"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"\"12.5px\"","output":"{\"value\":12.5,\"unit\":\"px\"}"},{"input":"\"0.75rem\"","output":"{\"value\":0.75,\"unit\":\"rem\"}"}],"starter_code_by_language":{"JavaScript":"function parseCssLengthToken(token) {\n  throw new Error(\"Not implemented\");\n}","Python":"def parse_css_length_token(token):\n    raise NotImplementedError"},"points":100},{"collection_slug":"web-development-fundamentals","slug":"normalize-upload-filename","title":"Normalize Upload Filename","problem_statement":"Keep only the final path component, replace control characters with underscores, and trim surrounding whitespace. Never return directory components.","difficulty":"Medium","topic_tags":["Web Fundamentals","Safe Data Handling"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"\"C:\\uploads\\  report final.pdf  \"","output":"report final.pdf"},{"input":"\"../avatar.png\"","output":"avatar.png"}],"starter_code_by_language":{"JavaScript":"function normalizeUploadFilename(filename) {\n  throw new Error(\"Not implemented\");\n}","Python":"def normalize_upload_filename(filename):\n    raise NotImplementedError"},"points":150}]$seed$) as seed(collection_slug text,slug text,title text,problem_statement text,difficulty text,topic_tags text[],constraints jsonb,examples jsonb,starter_code_by_language jsonb,points integer);

do $validate_seed$
begin
 if (select count(*) from coding_question_seed)<>20 or (select count(distinct slug) from coding_question_seed)<>20 then raise exception 'Expected exactly 20 distinct questions for web-development-fundamentals.'; end if;
 if (select count(distinct title) from coding_question_seed)<>20 or (select count(distinct problem_statement) from coding_question_seed)<>20 then raise exception 'Titles and problem statements must be distinct for web-development-fundamentals.'; end if;
 if exists(select 1 from coding_question_seed where slug=any(array['paginate-items','validate-hex-color','merge-query-parameters','parse-cookie-header','format-byte-count','escape-html-text','validate-url-slug'])) then raise exception 'Seed duplicates a pre-existing web-development-fundamentals slug.'; end if;
 if exists(select 1 from coding_question_seed s where char_length(btrim(s.title))<10 or char_length(btrim(s.problem_statement))<100 or s.difficulty not in ('Easy','Medium','Hard') or jsonb_typeof(s.constraints)<>'array' or jsonb_array_length(s.constraints)<2 or jsonb_typeof(s.examples)<>'array' or jsonb_array_length(s.examples)<2 or jsonb_typeof(s.starter_code_by_language)<>'object' or not(s.starter_code_by_language ? 'JavaScript') or not(s.starter_code_by_language ? 'Python') or nullif(btrim(s.starter_code_by_language->>'JavaScript'),'') is null or nullif(btrim(s.starter_code_by_language->>'Python'),'') is null or position('Not implemented' in s.starter_code_by_language->>'JavaScript')=0 or position('NotImplementedError' in s.starter_code_by_language->>'Python')=0 or exists(select 1 from jsonb_array_elements(s.examples) e(value) where jsonb_typeof(e.value)<>'object' or e.value->>'input' is null or e.value->>'output' is null or e.value->>'input' in ('[]','[null]','null','') or e.value->>'output' in ('[]','[null]'))) then raise exception 'Question quality validation failed for web-development-fundamentals.'; end if;
 if (select count(*) from public.coding_test_sets where slug='web-development-fundamentals' and publication_status='published')<>1 then raise exception 'Expected one published collection: web-development-fundamentals.'; end if;
 if (select count(*) from public.coding_test_sets where slug='web-development-fundamentals' and publication_status='published' and jsonb_array_length(supported_languages)=2 and supported_languages @> '["JavaScript","Python"]'::jsonb)<>1 then raise exception 'Expected JavaScript and Python support for web-development-fundamentals.'; end if;
 if (select count(*) from public.coding_questions q join public.coding_test_sets c on c.id=q.collection_id where c.slug='web-development-fundamentals')<>7 then raise exception 'Expected exactly 7 existing questions in web-development-fundamentals.'; end if;
 if (select coalesce(max(q.question_order),0) from public.coding_questions q join public.coding_test_sets c on c.id=q.collection_id where c.slug='web-development-fundamentals')<>7 then raise exception 'Expected existing web-development-fundamentals orders to end at 7.'; end if;
end;
$validate_seed$;

with question_rows as (select collection.id collection_id,seed.*,coalesce(existing.max_order,0)+row_number() over(partition by collection.id order by seed.slug)::integer question_order from coding_question_seed seed join public.coding_test_sets collection on collection.slug=seed.collection_slug and collection.publication_status='published' cross join lateral(select max(q.question_order) max_order from public.coding_questions q where q.collection_id=collection.id) existing) insert into public.coding_questions(collection_id,slug,title,problem_statement,difficulty,topic_tags,constraints,examples,starter_code_by_language,points,publication_status,question_order) select collection_id,slug,title,problem_statement,difficulty,topic_tags,constraints,examples,starter_code_by_language,points,'published',question_order from question_rows on conflict(collection_id,slug) do nothing;

insert into public.coding_test_cases(question_id,case_order,test_input,expected_output,visibility) select question.id,example.ordinality::integer,example.value->>'input',example.value->>'output','visible' from coding_question_seed seed join public.coding_test_sets collection on collection.slug=seed.collection_slug join public.coding_questions question on question.collection_id=collection.id and question.slug=seed.slug cross join lateral jsonb_array_elements(seed.examples) with ordinality example(value,ordinality) on conflict(question_id,case_order) do nothing;

commit;
